      ".nl-manga-panel__body{display:flex;flex-direction:column;gap:clamp(8px,2vw,12px);}",
      ".nl-manga-panel__dialogues{display:flex;flex-direction:column;gap:clamp(8px,2vw,12px);}",
      /* ── 会話（顔と吹き出し）── */
