    const lid = String(src.liveId || "").trim().toLowerCase();
    const scheme = String(src.colorScheme || "light");
    const picked = Array.isArray(src.picked) ? src.picked : [];
    const gifts = Array.isArray(src.giftPicks) ? src.giftPicks : [];
